import { OrderKey, OrderRepository } from './repository';
import { ListRequest, Order, Page } from './types';

export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}

  list(request: ListRequest): Page {
    const { tenant, limit, cursor } = request;
    if (!tenant || !Number.isInteger(limit) || limit < 1 || limit > 100) {
      throw new Error('invalid request');
    }
    const after = cursor === undefined ? undefined : parseCursor(cursor);
    // One order beyond the page is fetched only to learn whether a further matching order exists.
    const found = this.repository.listAfter(tenant, after, limit + 1);
    const items = found.slice(0, limit);
    const nextCursor = found.length > limit ? formatCursor(items[items.length - 1]) : null;
    return { items, nextCursor };
  }
}

// A cursor is `createdAt + '|' + id` of the last order returned. Neither part contains '|'.
function parseCursor(cursor: unknown): OrderKey {
  if (typeof cursor !== 'string') throw new Error('invalid request');
  const parts = cursor.split('|');
  if (parts.length !== 2 || !parts[0] || !parts[1]) throw new Error('invalid request');
  return { createdAt: parts[0], id: parts[1] };
}

function formatCursor(order: Order): string {
  return order.createdAt + '|' + order.id;
}
EOF
