// ---- cursor pagination ----
// Expected results come from the request text, written independently of src/.
{
  const { OrderHandler: Handler } = require('../.build/handler');
  const { OrderRepository: Repo } = require('../.build/repository');

  const refCmp = (a, b) => (a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
  const keyOf = (o) => ({ createdAt: o.createdAt, id: o.id });
  const cursorOf = (o) => o.createdAt + '|' + o.id;
  const isInvalid = (err) => err instanceof Error && err.message === 'invalid request';
  const ids = (page) => page.items.map((x) => x.id);

  // Reference page: tenant filter, then strictly after the cursor key, then limit.
  const expectPage = (rows, tenant, limit, key) => {
    const matching = rows.filter((r) => r.tenant === tenant).sort(refCmp);
    const after = key === undefined ? matching : matching.filter((r) => refCmp(r, key) > 0);
    const items = after.slice(0, limit);
    return { items, nextCursor: after.length > limit ? cursorOf(items[items.length - 1]) : null };
  };

  // Deterministic xorshift32 generator, so any failure reproduces exactly.
  let seed = 0x2545f491;
  const rnd = (n) => { seed ^= seed << 13; seed ^= seed >>> 17; seed ^= seed << 5; return (seed >>> 0) % n; };

  // Dates include a prefix of another date; ids mix case, digits, punctuation and non-ASCII.
  const TENANTS = ['a', 'b', 'c'];
  const DATES = ['2026-01-01', '2026-01-01T00', '2026-01-02', '2026-01-10', '2026-02-01'];
  const CHARS = ['A', 'B', 'a', 'b', '0', '9', '-', '_', '.', ' ', 'é', 'Z'];
  const randomId = () => Array.from({ length: 1 + rnd(3) }, () => CHARS[rnd(CHARS.length)]).join('');

  const dataset = [];
  const used = new Set();
  while (dataset.length < 80) {
    const row = { id: randomId(), tenant: TENANTS[rnd(TENANTS.length)], createdAt: DATES[rnd(DATES.length)], total: dataset.length };
    const k = JSON.stringify([row.tenant, row.createdAt, row.id]);
    if (!used.has(k)) { used.add(k); dataset.push(row); }
  }
  const h = new Handler(new Repo(dataset));

  // 1. Full walks: every page equals the reference page; the walk covers each tenant order once, in order.
  for (const tenant of TENANTS) {
    assert.deepEqual(new Repo(dataset).list(tenant), dataset.filter((r) => r.tenant === tenant).sort(refCmp));
    for (const limit of [1, 2, 3, 7, 100]) {
      const collected = [];
      let cursor;
      let key;
      for (let guard = 0; ; guard++) {
        assert.ok(guard < 1000, 'pagination did not terminate');
        const page = h.list(cursor === undefined ? { tenant, limit } : { tenant, limit, cursor });
        assert.deepEqual(page, expectPage(dataset, tenant, limit, key));
        collected.push(...page.items);
        if (page.nextCursor === null) break;
        key = keyOf(page.items[page.items.length - 1]);
        cursor = page.nextCursor;
      }
      assert.deepEqual(collected, dataset.filter((r) => r.tenant === tenant).sort(refCmp));
    }
  }

  // 2. Arbitrary cursors: a live row's key (from any tenant) or a key that matches no row.
  for (let i = 0; i < 500; i++) {
    const tenant = TENANTS[rnd(TENANTS.length)];
    const limit = 1 + rnd(6);
    const key = rnd(2) === 0 ? keyOf(dataset[rnd(dataset.length)]) : { createdAt: DATES[rnd(DATES.length)], id: randomId() };
    assert.deepEqual(h.list({ tenant, limit, cursor: key.createdAt + '|' + key.id }), expectPage(dataset, tenant, limit, key));
  }

  // 3. A cursor whose own row was deleted still resumes strictly after its key.
  for (let i = 0; i < 200; i++) {
    const victim = dataset[rnd(dataset.length)];
    const remaining = dataset.filter((r) => r !== victim);
    const hd = new Handler(new Repo(remaining));
    const tenant = TENANTS[rnd(TENANTS.length)];
    const limit = 1 + rnd(5);
    assert.deepEqual(hd.list({ tenant, limit, cursor: cursorOf(victim) }), expectPage(remaining, tenant, limit, keyOf(victim)));
  }

  // 4. Inputs are not mutated: array order, array identity and row contents are unchanged.
  {
    const input = dataset.map((r) => ({ ...r }));
    const snapshot = JSON.stringify(input);
    const identity = input.slice();
    const repo = new Repo(input);
    const hi = new Handler(repo);
    for (const tenant of TENANTS) {
      hi.list({ tenant, limit: 2 });
      hi.list({ tenant, limit: 100, cursor: '2026-01-01|A' });
      repo.list(tenant);
    }
    assert.equal(JSON.stringify(input), snapshot);
    input.forEach((row, i) => assert.strictEqual(row, identity[i]));
  }

  // 5. Explicit scenarios.
  {
    // Original fixture: the first page is unchanged, and nextCursor marks the point to resume.
    const legacy = new Handler(new Repo([
      { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
      { id: 'x', tenant: 'b', createdAt: '2026-01-01', total: 3 },
      { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 }
    ]));
    const first = legacy.list({ tenant: 'a', limit: 1 });
    assert.deepEqual(ids(first), ['a']);
    assert.equal(first.nextCursor, '2026-01-01|a');
    const second = legacy.list({ tenant: 'a', limit: 1, cursor: first.nextCursor });
    assert.deepEqual(ids(second), ['b']);
    assert.equal(second.nextCursor, null);
    // A cursor taken from another tenant's row: resume at that position within tenant 'a'.
    assert.deepEqual(legacy.list({ tenant: 'a', limit: 5, cursor: '2026-01-01|x' }), { items: [legacy.list({ tenant: 'a', limit: 5 }).items[1]], nextCursor: null });

    // Equal dates ordered by id in code-unit order: 'A' < 'B' < 'a' < 'a0' < 'aa'.
    const ties = new Handler(new Repo([
      { id: 'a', tenant: 't', createdAt: '2026-05-05', total: 1 },
      { id: 'B', tenant: 't', createdAt: '2026-05-05', total: 1 },
      { id: 'aa', tenant: 't', createdAt: '2026-05-05', total: 1 },
      { id: 'A', tenant: 't', createdAt: '2026-05-05', total: 1 },
      { id: 'a0', tenant: 't', createdAt: '2026-05-05', total: 1 },
      { id: 'c', tenant: 't', createdAt: '2026-05-04', total: 1 }
    ]));
    const p1 = ties.list({ tenant: 't', limit: 2 });
    assert.deepEqual(ids(p1), ['c', 'A']);
    assert.equal(p1.nextCursor, '2026-05-05|A');
    const p2 = ties.list({ tenant: 't', limit: 2, cursor: p1.nextCursor });
    assert.deepEqual(ids(p2), ['B', 'a']);
    assert.equal(p2.nextCursor, '2026-05-05|a');
    const p3 = ties.list({ tenant: 't', limit: 2, cursor: p2.nextCursor });
    assert.deepEqual(ids(p3), ['a0', 'aa']);
    assert.equal(p3.nextCursor, null);

    // '2026-01-01T00' sorts after '2026-01-01' by date, even though '|' would sort after 'T' in a joined key.
    const prefix = new Handler(new Repo([
      { id: 'x', tenant: 't', createdAt: '2026-01-01', total: 1 },
      { id: 'y', tenant: 't', createdAt: '2026-01-01T00', total: 1 },
      { id: 'z', tenant: 't', createdAt: '2026-01-01', total: 1 }
    ]));
    const q1 = prefix.list({ tenant: 't', limit: 2 });
    assert.deepEqual(ids(q1), ['x', 'z']);
    assert.deepEqual(ids(prefix.list({ tenant: 't', limit: 2, cursor: q1.nextCursor })), ['y']);

    // The cursor's own row is removed from the live array between pages.
    const live = [
      { id: 'a1', tenant: 't', createdAt: '2026-03-01', total: 1 },
      { id: 'a2', tenant: 't', createdAt: '2026-03-02', total: 1 },
      { id: 'a3', tenant: 't', createdAt: '2026-03-03', total: 1 }
    ];
    const liveH = new Handler(new Repo(live));
    const l1 = liveH.list({ tenant: 't', limit: 2 });
    assert.equal(l1.nextCursor, '2026-03-02|a2');
    live.splice(1, 1);
    const l2 = liveH.list({ tenant: 't', limit: 2, cursor: l1.nextCursor });
    assert.deepEqual(ids(l2), ['a3']);
    assert.equal(l2.nextCursor, null);

    // nextCursor is null when only tenant 'a' has no further order, even though tenant 'b' does.
    const look = new Handler(new Repo([
      { id: 'a1', tenant: 'a', createdAt: '2026-01-01', total: 1 },
      { id: 'a2', tenant: 'a', createdAt: '2026-01-05', total: 1 },
      { id: 'b1', tenant: 'b', createdAt: '2026-01-02', total: 1 },
      { id: 'b2', tenant: 'b', createdAt: '2026-01-03', total: 1 },
      { id: 'b3', tenant: 'b', createdAt: '2026-01-04', total: 1 }
    ]));
    assert.deepEqual(ids(look.list({ tenant: 'a', limit: 1, cursor: '2026-01-01|a1' })), ['a2']);
    assert.equal(look.list({ tenant: 'a', limit: 1, cursor: '2026-01-01|a1' }).nextCursor, null);
    // Exactly `limit` orders left: no further order, so nextCursor is null.
    assert.equal(look.list({ tenant: 'a', limit: 2 }).nextCursor, null);
    assert.equal(look.list({ tenant: 'a', limit: 1 }).nextCursor, '2026-01-01|a1');

    // A cursor beyond all orders, or for a tenant with none, gives an empty page.
    assert.deepEqual(look.list({ tenant: 'a', limit: 1, cursor: 'zzz|zzz' }), { items: [], nextCursor: null });
    assert.deepEqual(look.list({ tenant: 'nobody', limit: 1 }), { items: [], nextCursor: null });
  }

  // 6. Invalid requests throw Error('invalid request').
  {
    const bad = [
      { tenant: '', limit: 1 },
      { tenant: undefined, limit: 1 },
      { tenant: 'a', limit: 0 },
      { tenant: 'a', limit: 101 },
      { tenant: 'a', limit: 1.5 },
      { tenant: 'a', limit: NaN },
      { tenant: 'a', limit: '5' },
      { tenant: 'a' },
      { tenant: 'a', limit: 1, cursor: '' },
      { tenant: 'a', limit: 1, cursor: 'nodate' },
      { tenant: 'a', limit: 1, cursor: '2026-01-01|' },
      { tenant: 'a', limit: 1, cursor: '|a' },
      { tenant: 'a', limit: 1, cursor: '|' },
      { tenant: 'a', limit: 1, cursor: 'a|b|c' },
      { tenant: 'a', limit: 1, cursor: 'a||b' },
      { tenant: 'a', limit: 1, cursor: 42 },
      { tenant: 'a', limit: 1, cursor: null }
    ];
    for (const req of bad) assert.throws(() => h.list(req), isInvalid, 'expected invalid request: ' + JSON.stringify(req));
    // Boundaries that are accepted, and an omitted cursor (or undefined) is the first page.
    assert.equal(h.list({ tenant: 'a', limit: 1 }).items.length, 1);
    assert.doesNotThrow(() => h.list({ tenant: 'a', limit: 100 }));
    assert.doesNotThrow(() => h.list({ tenant: 'a', limit: 1, cursor: 'zzz|zzz' }));
    assert.deepEqual(h.list({ tenant: 'a', limit: 3, cursor: undefined }), h.list({ tenant: 'a', limit: 3 }));
  }
}
EOF
