import { Order } from './types';

/** An order's position in list order: createdAt first, then id. */
export interface OrderKey { createdAt: string; id: string }

// Lexicographic (UTF-16 code unit) string order on createdAt, then id.
function compareOrders(a: OrderKey, b: OrderKey): number {
  return a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 :
    a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  list(tenant: string): Order[] {
    return this.rows.filter(row => row.tenant === tenant).sort(compareOrders);
  }

  /**
   * Up to `limit` orders for `tenant` that sort strictly after `after`, or the
   * first orders when `after` is undefined. The tenant filter is applied before
   * the position. The position is compared by value, so it stays valid when the
   * row it came from has been deleted or belongs to another tenant. Does not
   * modify `rows`.
   */
  listAfter(tenant: string, after: OrderKey | undefined, limit: number): Order[] {
    const sorted = this.list(tenant);
    if (after === undefined) return sorted.slice(0, limit);
    return sorted.filter(row => compareOrders(row, after) > 0).slice(0, limit);
  }
}
